const PARSED = new Map(); // lang -> [{ id, title, author, blurb }]

export function gutenbergShelf(lang) {
  if (!PARSED.has(lang)) {
    const packed = SHELVES[lang] ?? "";
    PARSED.set(
      lang,
      packed
        .split("\n")
        .filter(Boolean)
        .map((line) => {
          const tab1 = line.indexOf("\t");
          const tab2 = line.indexOf("\t", tab1 + 1);
          const tab3 = line.indexOf("\t", tab2 + 1);
          return {
            id: line.slice(0, tab1),
            title: line.slice(tab1 + 1, tab2),
            author: line.slice(tab2 + 1, tab3),
            blurb: line.slice(tab3 + 1),
          };
        }),
    );
  }
  return PARSED.get(lang);
}

const BY_ID = new Map(); // id -> row (all shelves, built on first use)

export function gutenbergBook(id) {
  if (BY_ID.size === 0) {
    for (const lang of GUTENBERG_SHELF_LANGUAGES) {
      for (const row of gutenbergShelf(lang)) BY_ID.set(row.id, { ...row, language: lang });
    }
  }
  return BY_ID.get(String(id)) ?? null;
}
